# What a seller could do before access became a checklist.
SELLER_PERMS = ["pos.close", "pos.discount", "pos.return", "pos.sell"]


def sellers_to_staff(apps, schema_editor):
    Group = apps.get_model("auth", "Group")
    StaffAccess = apps.get_model("accounts", "StaffAccess")
    group = Group.objects.filter(name="seller").first()
    if group is None:
        return
    for user in group.user_set.filter(is_staff=False):
        StaffAccess.objects.get_or_create(user=user, defaults={"perms": SELLER_PERMS})
    group.delete()


def staff_to_sellers(apps, schema_editor):
    Group = apps.get_model("auth", "Group")
    StaffAccess = apps.get_model("accounts", "StaffAccess")
    group, _ = Group.objects.get_or_create(name="seller")
    for access in StaffAccess.objects.all():
        group.user_set.add(access.user_id)


